'use strict';
const routes=[['library','▤','书架'],['import','↥','导入小说'],['chapters','≡','章节工作台'],['director','⌘','AI 导演'],['voices','≋','音色库'],['queue','◷','任务队列'],['listen','▷','试听'],['export','↧','导出'],['settings','⚙','设置']];
const titles=['雾中的信','旧日回声','潮汐之间','深夜来电','未寄出的信','雨停以后','灯塔来客','海的另一边'];
const sample=['暮色落进海面的时候，林舟收到了一封没有署名的信。信封上的字迹很淡，像是被海风吹散了一半。','他沿着旧码头向前走。灯塔亮起的那一刻，远处有人轻轻叫了他的名字。','“你还是来了。”沈雾站在门边，声音比夜色更轻。','林舟没有回答。他把那封信放在桌上，等着窗外的雨慢慢停下来。'];
const voices=[['远山','沉稳 · 低沉 · 叙述'],['清禾','温柔 · 清晰 · 青年'],['墨白','成熟 · 克制 · 悬疑'],['星野','明亮 · 自然 · 青年'],['南枝','细腻 · 温暖 · 叙述'],['迟川','舒缓 · 浑厚 · 叙述']];
const state={selected:new Set([1,2,3,4,5,6]),chapter:7,voice:'远山',filter:'全部音色',segment:0,speed:'0.95',emotion:'克制',pause:'450',saved:false,queuePaused:false,exportReady:false,settingsTab:'语音服务',fileName:'雾海来信.txt',fileText:null,importChapters:null,importBuffer:null};
const $=s=>document.querySelector(s);const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const wave=(count=65)=>`<div class="wave" aria-hidden="true">${Array.from({length:count},(_,i)=>`<i style="height:${15+Math.abs(Math.sin(i*2.43)*Math.cos(i*.18))*80}%"></i>`).join('')}</div>`;
const cover=(name='雾海来信',i=0)=>`<div class="cover c${i}"><span class="cover-title">${name}</span><small>声页 · 故事集</small><span class="cover-number">0${i+1}</span></div>`;
const head=(title,sub,actions='')=>`<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;
const btn=(text,action,cls='')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
const tag=(text,cls='')=>`<span class="badge ${cls}">${text}</span>`;
const chapterName=i=>`第${['一','二','三','四','五','六','七','八'][i-1]}章　${titles[i-1]}`;
function chapterList(){return `<div class="chapter-list">${titles.map((t,i)=>`<button data-chapter="${i+1}" class="${state.chapter===i+1?'active':''}"><small>0${i+1}</small>　${t}</button>`).join('')}</div>`}
function library(){return head('我的书架','把每一页，变成可以听见的故事。',btn('＋ 导入小说','go-import','primary'))+`<section class="hero-work">${cover()}<div><span class="eyebrow">继续上次的创作</span><h2>雾海来信</h2><p class="muted">24 章 · 12 章已完成 · 旁白 ${state.voice}</p><div class="progress"><i style="width:50%"></i></div><div class="actions" style="margin-top:18px">${btn('继续制作 ↗','go-chapters','primary')}${btn('▷ 试听成品','go-listen')}</div></div><div class="hero-wave">${wave()}<small><span>第七章 · 灯塔来客</span><span>12:48</span></small></div></section><div class="section-head"><h2>全部作品 <small>04</small></h2><span class="muted">最近编辑优先</span></div><section class="books">${['雾海来信','山间慢信','长夜回声','春日列车'].map((n,i)=>`<article class="book"><button data-action="go-chapters" aria-label="打开${n}">${cover(n,i)}<h3>${n}</h3><small>${['12 / 24 章已完成','8 / 8 章已完成','等待选择音色','3 / 16 章已完成'][i]}</small><div class="progress"><i style="width:${[50,100,0,18][i]}%"></i></div></button></article>`).join('')}</section><div class="section-head"><h2>最近制作</h2><a href="#queue" class="muted">全部任务 ↗</a></div><div class="table-wrap"><table><thead><tr><th>章节</th><th>作品</th><th>音色</th><th>状态</th><th></th></tr></thead><tbody><tr><td>第七章　灯塔来客</td><td class="muted">雾海来信</td><td>${state.voice}</td><td>${tag('已完成','ok')}</td><td>${btn('▷ 试听','go-listen','small')}</td></tr></tbody></table></div>`}
function importing(){const parsed=state.importChapters;return head('导入小说','先把章节理清，再让故事开口。')+`<div class="steps"><span>01　上传文件</span><span class="active">02　校对分章</span><span>03　确认创建</span></div><div class="grid-two" style="grid-template-columns:310px minmax(0,1fr)"><aside class="panel"><div class="dropzone"><h3>拖入或选择小说</h3><small>原型可本地预览 TXT · EPUB 见计划</small><input type="file" id="novel-file" accept=".txt" aria-label="选择TXT小说文件"></div><h3>${escape(state.fileName)}</h3><div class="field" style="margin-top:18px"><label for="encoding">文本编码</label><select id="encoding"><option>UTF-8</option><option>GB18030</option></select></div><div class="row-between"><h3>识别目录</h3><small>${parsed?parsed.length:24} 章</small></div>${parsed?`<div class="chapter-list">${parsed.slice(0,30).map((c,i)=>`<button data-import-chapter="${i}">${escape(c.title)}</button>`).join('')}</div>`:chapterList()}<div class="note">分章结果需核对，原型不会上传文件。</div></aside><section class="panel reader"><div class="row-between"><small>原文预览</small>${btn('分章规则','rules','small')}</div><div id="import-preview" style="margin-top:24px">${state.fileText?`<p style="white-space:pre-wrap">${escape(state.fileText.slice(0,3600))}</p>`:`<h2>第一章　雾中的信</h2>${sample.map(p=>`<p>${p}</p>`).join('')}`}</div><div class="actions" style="margin-top:30px">${btn('确认分章 →','confirm-import','primary')}${btn('返回书架','go-library')}</div></section></div>`}
function chapters(){return head('雾海来信','24 章 · 12 章已完成 · 3 章等待制作',btn('进入 AI 导演','go-director')+btn('生成所选','generate','primary'))+`<div class="filters">${tag('单人旁白','lime')}<span class="muted">默认声音 ${state.voice}</span><span class="muted">合成语速 1.0×</span><span style="flex:1"></span><a href="#voices">更换音色 ↗</a></div><div class="note">${state.saved?'第七章的朗读设置已修改，已有音频仍可试听；重新生成后形成新版本。':'先用一小段确认声音，再生成选中的章节。所有任务与数值均为演示。'}</div><div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="select-all" aria-label="全选章节"></th><th>章节</th><th>音色</th><th>状态</th><th>时长</th><th>操作</th></tr></thead><tbody>${titles.map((t,i)=>`<tr><td><input type="checkbox" data-select="${i+1}" ${state.selected.has(i+1)?'checked':''} aria-label="选择第${i+1}章"></td><td>${chapterName(i+1)}</td><td class="muted">${state.voice}</td><td>${tag(i===6&&state.saved?'待更新':['已完成','已完成','已完成','已完成','已完成','已完成','待生成','需要确认'][i],i<6?'ok':'warn')}</td><td class="muted">${i<6?['10:32','14:08','09:45','11:26','13:05','08:54'][i]:'—'}</td><td><button class="small quiet" data-director="${i+1}">导演 ↗</button><button class="small quiet" data-action="go-listen">▷</button></td></tr>`).join('')}</tbody></table></div><div class="row-between" style="margin-top:24px"><span id="selected-count" class="muted">已选 ${state.selected.size} 章</span><div class="actions">${btn('试听','go-listen')}${btn('导出音频','go-export')}</div></div>`}
function director(){return head(chapterName(state.chapter),'雾海来信 / AI 导演 · 逐段调整朗读',btn(state.saved?'已保存':'保存设置','save')+btn('生成本章','generate-one','primary'))+`<div class="director"><aside class="panel"><h3>章节目录</h3>${chapterList()}</aside><section class="panel"><div class="row-between"><h3>朗读脚本</h3>${tag('AI 建议 · 演示','lime')}</div><div class="script">${sample.map((p,i)=>`<div class="segment ${state.segment===i?'active':''}" role="button" tabindex="0" data-segment="${i}" aria-label="选择第${i+1}个片段"><small>0${i+1}　${['旁白','旁白','沈雾','旁白'][i]}</small>${tag(['平静','舒缓','轻声','克制'][i])}<p>${p}</p></div>`).join('')}</div><div class="timeline"><div class="ruler"><span>00:00</span><span>00:10</span><span>00:20</span><span>00:30</span></div>${wave()}<div class="row-between"><small>示意音轨 · 尚无真实音频</small>${btn('▷ 试听选段','preview','small')}</div></div></section><aside class="panel inspector"><h3>片段 0${state.segment+1} · 朗读设置</h3><div class="field"><label for="voice">音色</label><select id="voice">${voices.map(v=>`<option ${state.voice===v[0]?'selected':''}>${v[0]}</option>`).join('')}</select></div><div class="field"><label for="emotion">情绪</label><select id="emotion">${['克制','平静','温柔','紧张','喜悦','悲伤'].map(e=>`<option ${state.emotion===e?'selected':''}>${e}</option>`).join('')}</select></div><div class="field"><label for="speed">合成语速 <b id="speed-val">${state.speed}×</b></label><input id="speed" type="range" min="0.6" max="1.4" step="0.05" value="${state.speed}"></div><div class="field"><label for="pause">句尾停顿（毫秒）</label><input id="pause" type="number" min="0" max="3000" step="50" value="${state.pause}"></div><div class="note"><h3>AI 建议</h3><p style="margin:8px 0">这段叙述适合稍慢的语速，句尾留白，保持克制。</p>${btn('应用建议','apply-ai','small')}</div><small>可用参数随实际引擎能力变化。</small></aside></div>`}
function voicePage(){return head('为故事挑选声音','先听，再决定。这里的音色名称为设计演示。')+`<div class="filters">${['全部音色','已收藏'].map(f=>`<button data-filter="${f}" class="${f===state.filter?'active':''}">${f}</button>`).join('')}<span style="flex:1"></span><input class="search" id="voice-search" aria-label="搜索音色" placeholder="搜索音色或特征"></div><div class="grid-two"><section class="voice-list" id="voice-list">${voiceRows()}</section><aside class="panel"><span class="eyebrow">当前选择</span><h1 style="margin:14px 0">${state.voice}</h1>${wave(40)}<div class="actions">${tag('中文')}${tag('旁白')}${tag('情绪可调','ok')}</div><div class="field" style="margin-top:26px"><label for="sample-text">试听文本</label><textarea id="sample-text">暮色落进海面的时候，他收到了一封没有署名的信。</textarea></div><div class="actions">${btn('▷ 试听声音','preview','primary')}${btn('应用到本书','apply-voice')}</div><div class="note">正式版显示服务商、能力与真实音色 ID，音色列表从服务端加载。</div></aside></div>`}
function voiceRows(query=''){return voices.filter((v,i)=>(state.filter!=='已收藏'||i<2)&&v.join('').includes(query)).map((v,i)=>`<div class="voice-row ${v[0]===state.voice?'selected':''}"><div class="soundprint" aria-hidden="true">≋</div><div class="voice-text"><h3>${v[0]} ${i<2?'☆':''}</h3><small>${v[1]}</small></div>${wave(25)}<button class="small" data-voice="${v[0]}">选择</button><button class="small quiet" data-action="preview" aria-label="试听${v[0]}">▷</button></div>`).join('')||'<div class="empty">没有匹配的音色，请换一个关键词。</div>'}
function queue(){return head('任务队列','正式版关闭页面后，任务仍会继续。当前为模拟队列。',btn(state.queuePaused?'恢复队列':'暂停队列','pause-queue'))+`<div class="grid-two"><section><div class="panel"><div class="row-between"><div><span class="eyebrow">${state.queuePaused?'已暂停调度':'正在合成'}</span><h2 style="margin-top:10px">雾海来信 · 第十三章</h2></div>${tag(state.queuePaused?'已暂停':'56%','lime')}</div><div class="progress" style="margin-top:28px"><i style="width:56%"></i></div><div class="row-between"><small>18 / 32 片段</small><small>${state.queuePaused?'当前请求完成后暂停':'正在处理片段 19'}</small></div><div class="actions" style="margin-top:20px">${btn('取消本章','cancel-job','small')}</div></div><div class="section-head"><h2>等待中 <small>02</small></h2></div>${['第十四章 · 回到码头','第十五章 · 无声的回答'].map(t=>`<div class="job row-between"><div><h3>${t}</h3><small>雾海来信 · 等待前序任务</small></div>${tag('排队中')}</div>`).join('')}<div class="section-head"><h2>需要处理</h2></div><div class="job"><div class="row-between"><div><h3>第九章 · 雨后的约定</h3><small class="danger">语音服务额度不足，任务已暂停</small></div>${tag('未完成','warn')}</div><div class="actions" style="margin-top:15px">${btn('检查设置','go-settings','small')}${btn('重试失败项','retry','small')}</div></div></section><aside class="panel"><h3>当前任务阶段</h3><div class="phase-list"><span>✓　分析文本</span><span class="active">◉　合成片段</span><span>○　拼接章节</span><span>○　检查音频</span></div><div class="summary-line"><span>声音</span><b>${state.voice}</b></div><div class="summary-line"><span>完成片段</span><b>18 / 32</b></div><div class="summary-line"><span>费用</span><b>价格未配置</b></div><div class="note">暂停会停止领取新任务，已提交的请求可能继续完成。</div></aside></div>`}
function listen(){return head('听见故事','试听、标记问题，再把成品带走。',btn('返回导演','go-director')+btn('导出本章','go-export'))+`<div class="listen"><aside class="panel">${cover()}<h2 style="margin-top:20px">雾海来信</h2><small>旁白 ${state.voice} · 24 章</small>${chapterList()}</aside><section class="listen-stage"><span class="eyebrow">雾海来信 / 章节试听</span><h1>${chapterName(state.chapter)}</h1>${wave(105)}<small>示意波形 · 载入本地音频后可使用下方真实播放器</small><div class="listen-controls">${btn('↶ 15','back')}${btn('▶','play','play')}${btn('15 ↷','forward')}</div><div class="actions" style="justify-content:center">${btn('标记问题','mark')}${btn('载入本地音频','load-audio')}</div><div class="excerpt"><div class="row-between"><small>原文片段</small>${tag('片段 01')}</div><p style="margin-top:20px">${sample[0]}</p><p class="muted" style="margin-top:15px">${sample[1]}</p></div></section></div>`}
function exportPage(){return head('导出有声书','每章独立保存，也可以一次带走。')+`<div class="grid-two"><section><div class="row-between" style="margin-bottom:20px"><h2>选择章节</h2>${btn('选择全部已完成','select-completed','small')}</div><div class="table-wrap"><table><thead><tr><th></th><th>章节</th><th>版本</th><th>时长</th></tr></thead><tbody>${titles.map((t,i)=>`<tr><td><input type="checkbox" data-select="${i+1}" ${i>=6?'disabled':''} ${i<6&&state.selected.has(i+1)?'checked':''} aria-label="导出第${i+1}章"></td><td>${chapterName(i+1)}</td><td>${i<6?tag('v1','ok'):tag('未生成','warn')}</td><td class="muted">${i<6?'12:48':'—'}</td></tr>`).join('')}</tbody></table></div><div class="note">2 章尚未生成，不会包含在导出包中。</div><div class="section-head"><h2>导出历史</h2></div><div class="job row-between"><div><h3>${state.exportReady?'本次选择清单已生成':'暂无本次导出'}</h3><small>原型只导出 JSON 清单，不生成音频文件。</small></div>${state.exportReady?btn('下载清单','download-manifest','small'):tag('等待选择')}</div></section><aside class="panel"><h3>导出设置</h3><div class="field" style="margin-top:24px"><label for="format">音频格式</label><select id="format"><option>MP3</option><option>WAV</option></select></div><div class="field"><label for="quality">MP3 码率</label><select id="quality"><option>192 kbps</option><option>128 kbps</option><option>256 kbps</option></select></div><small>文件命名预览</small><div class="file-preview">雾海来信/\n001_雾中的信.mp3\n002_旧日回声.mp3</div><div class="summary-line"><span>已选章节</span><b id="export-count">${[...state.selected].filter(n=>n<7).length} 章</b></div><div class="note">正式版会异步打包，并保留这次选择的音频版本。</div>${btn('生成导出清单','build-export','primary')}</aside></div>`}
function settings(){const tab=state.settingsTab;return head('设置','连接声音，管理你的工作室。')+`<div class="tabs">${['语音服务','AI 分析','存储','账户'].map(t=>`<button data-tab="${t}" class="${t===tab?'active':''}">${t}</button>`).join('')}</div><div class="grid-two"><section class="panel">${tab==='存储'?`<h2>数据与备份</h2><div class="summary-line"><span>持久目录</span><b>/data</b></div><div class="summary-line"><span>示例已用空间</span><b>2.4 GB</b></div><div class="note">正式版在此提供数据库与音频备份、保留期和空间检查。</div>${btn('查看备份方案','backup')}`:tab==='账户'?`<h2>工作室账户</h2><p class="muted" style="margin:18px 0">首次启动创建管理员，关闭公开注册。</p>${btn('预览登录','login')}${btn('预览首次设置','setup')}`:`<h2>${tab==='AI 分析'?'AI 内容分析':'语音合成服务'}</h2><p class="muted" style="margin:10px 0 25px">${tab==='AI 分析'?'解析角色、情感和朗读节奏。':'使用云端服务，NAS 无需 GPU。'}</p><div class="field"><label for="provider">服务类型</label><select id="provider"><option>${tab==='AI 分析'?'兼容接口':'云端语音服务'}</option><option>自托管服务</option></select></div><div class="field"><label for="endpoint">API 地址</label><input id="endpoint" placeholder="https://your-provider.example/api" autocomplete="off"></div><div class="field"><label for="key">API 密钥</label><input id="key" type="password" placeholder="设计原型，请勿输入真实密钥" autocomplete="off"></div><div class="field"><label for="model">模型名称</label><input id="model" placeholder="选择或填写服务支持的模型"></div><div class="actions">${btn('测试连接','test-connection')}${btn('保存设置','save-settings','primary')}</div><div class="note">原型不发送请求或保存凭据。正式版仅在服务端保存密钥。</div>`}</section><aside><div class="panel"><h3>首次使用</h3><div class="phase-list"><span>01　创建管理员</span><span>02　配置语音服务</span><span>03　生成短试听</span></div>${btn('预览设置向导','setup','small')}</div><div class="note">云端 AI 或语音合成会将所选文本发送至对应服务商。使用本地服务可另行配置。</div><div class="panel"><h3>部署方式</h3><div class="summary-line"><span>Web 端口</span><b>8780</b></div><div class="summary-line"><span>持久数据</span><b>/data</b></div><small>此处为部署设计，尚未提供镜像。</small></div></aside></div>`}
const pages={library,import:importing,chapters,director,voices:voicePage,queue,listen,export:exportPage,settings};
function render(){const route=location.hash.slice(1)||'library';const r=pages[route]?route:'library';$('#nav').innerHTML=routes.map(([id,icon,name])=>`<a href="#${id}" class="${r===id?'active':''}" ${r===id?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${name}</a>`).join('');$('#crumb').textContent=routes.find(x=>x[0]===r)[2];$('#main').innerHTML=pages[r]();document.title=`${$('#crumb').textContent} · 声页`;$('.sidebar').classList.remove('open')}
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function modal(title,body){$('#dialog-content').innerHTML=`<h2>${title}</h2><div class="dialog-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal()}
function auth(setup=false){modal(setup?'创建你的工作室':'登录声页',`<p style="margin-bottom:20px">设计表单预览，不会创建账户。</p><form id="auth-form"><div class="field"><label for="username">用户名</label><input id="username" required autocomplete="username" placeholder="工作室管理员"></div><div class="field"><label for="password">密码</label><input id="password" required minlength="8" type="password" autocomplete="new-password" placeholder="至少 8 位"></div><button type="submit" class="primary">${setup?'创建并配置服务':'登录'}</button></form>`)}
document.addEventListener('submit',e=>{if(e.target.id==='auth-form'){e.preventDefault();$('#dialog').close();location.hash='settings';toast('表单通过本地校验；原型未创建或登录账户。')}});
document.addEventListener('click',e=>{const target=e.target.closest('button,[data-segment]');if(!target)return;if(target.dataset.chapter){state.chapter=+target.dataset.chapter;render();return}if(target.dataset.director){state.chapter=+target.dataset.director;location.hash='director';return}if(target.dataset.segment){state.segment=+target.dataset.segment;render();return}if(target.dataset.voice){state.voice=target.dataset.voice;render();return}if(target.dataset.filter){state.filter=target.dataset.filter;render();return}if(target.dataset.tab){state.settingsTab=target.dataset.tab;render();return}if(target.dataset.importChapter){const c=state.importChapters[+target.dataset.importChapter];$('#import-preview').innerHTML=`<h2>${escape(c.title)}</h2><p style="white-space:pre-wrap">${escape(c.text.slice(0,3600))}</p>`;return}const a=target.dataset.action;if(!a)return;if(a.startsWith('go-')){location.hash=a.slice(3);return}const actions={menu:()=>$('.sidebar').classList.toggle('open'),close:()=>$('#dialog').close(),login:()=>auth(),setup:()=>auth(true),preview:()=>modal('试听前先连接语音服务','当前是设计原型，未连接语音引擎。正式版会用当前音色合成所选文本。你可以载入本地音频，体验播放、拖动与倍速。<div class="actions" style="margin-top:20px">'+btn('载入音频','load-audio','primary')+btn('查看服务设置','to-settings')+'</div>'),'to-settings':()=>{$('#dialog').close();location.hash='settings'},'load-audio':()=>{$('#dialog').close();$('#audio-file').click()},play:playAudio,back:()=>{if(Number.isFinite(audio.duration))audio.currentTime=Math.max(0,audio.currentTime-15)},forward:()=>{if(Number.isFinite(audio.duration))audio.currentTime=Math.min(audio.duration,audio.currentTime+15)},save:()=>{state.saved=true;render();toast('朗读设置已保留在本次原型会话中；音频标记为待更新。')},'apply-ai':()=>{state.speed='0.95';state.emotion='克制';state.pause='450';render();toast('已应用示例建议，可继续手动修改。')},'apply-voice':()=>{toast(`已将 ${state.voice} 设为演示项目的默认音色。`);location.hash='chapters'},generate:()=>generate(false),'generate-one':()=>generate(true),'confirm-generation':()=>{$('#dialog').close();location.hash='queue';toast('已进入模拟队列，没有调用语音服务。')},'pause-queue':()=>{state.queuePaused=!state.queuePaused;render()},'cancel-job':()=>modal('取消本章？','正式版停止后续片段，保留已完成音频。已提交到服务商的请求可能仍会完成。<div style="margin-top:20px">'+btn('确认取消（演示）','confirm-cancel','primary')+'</div>'),'confirm-cancel':()=>{$('#dialog').close();state.queuePaused=true;render();toast('模拟任务已停止后续调度。')},retry:()=>toast('重试流程演示：先补充额度，再重试失败片段。'),mark:()=>modal('标记试听问题','<div class="field"><label for="issue">问题说明</label><textarea id="issue" placeholder="例如：人名读音不正确"></textarea></div>'+btn('保存标记','save-mark','primary')),'save-mark':()=>{$('#dialog').close();toast('问题已在本次原型会话中标记，可返回导演修改。')},'select-completed':()=>{state.selected=new Set([1,2,3,4,5,6]);render()},'build-export':buildExport,'download-manifest':downloadManifest,'test-connection':()=>modal('连接测试预览','原型没有后端，不会发送密钥。正式版分别检查地址、身份凭据、模型与音色能力，并显示具体错误。'),'save-settings':()=>toast('设计原型不保存凭据，请在正式部署后配置。'),backup:()=>modal('备份与恢复','正式版备份 SQLite 数据库、原文、音频及加密主密钥。数据库应使用在线备份或停止写入后复制，恢复后检查文件引用与权限。'),rules:()=>modal('分章规则','原型按独立的“第 X 章 / 回 / 节”标题识别 TXT。正式版还支持 EPUB 目录、中文编码预览、合并、拆分与原文偏移验证。'),'confirm-import':()=>{location.hash='chapters';toast('分章流程演示完成。当前工作台仍显示示例书籍，文件未上传。')}};actions[a]?.()});
function generate(one){const n=one?1:state.selected.size;if(!n){toast('请先选择至少一章。');return}modal('确认生成范围',`<p>已选择 ${n} 章 · 音色 ${state.voice}</p><p style="margin-top:12px">价格未配置。正式版会显示实际字数和费用估算，并保存参数快照。</p><div class="note">当前仅进入模拟任务，不提交付费请求。</div>${btn('查看模拟队列','confirm-generation','primary')}`)}
function buildExport(){const selected=[...state.selected].filter(n=>n<7);if(!selected.length){toast('请至少选择一个已完成章节。');return}state.manifest={demo:true,notice:'设计原型清单，不包含音频',book:'雾海来信',format:$('#format').value,chapters:selected.map(i=>({index:i,title:titles[i-1],audioVersion:1}))};state.exportReady=true;render();toast('导出清单已生成，可以下载检查章节顺序。')}
function downloadManifest(){if(!state.manifest)return;const blob=new Blob([JSON.stringify(state.manifest,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='声页-导出演示清单.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.addEventListener('change',async e=>{const t=e.target;if(t.dataset.select){t.checked?state.selected.add(+t.dataset.select):state.selected.delete(+t.dataset.select);if($('#selected-count'))$('#selected-count').textContent=`已选 ${state.selected.size} 章`;if($('#export-count'))$('#export-count').textContent=`${[...state.selected].filter(n=>n<7).length} 章`}if(t.id==='select-all'){state.selected=t.checked?new Set([1,2,3,4,5,6,7,8]):new Set();render()}if(['voice','emotion','pause'].includes(t.id))state[t.id]=t.value;if(t.id==='format'){$('#quality').disabled=t.value==='WAV';$('.file-preview').textContent=`雾海来信/\n001_雾中的信.${t.value.toLowerCase()}\n002_旧日回声.${t.value.toLowerCase()}`}if(t.id==='novel-file'){const f=t.files[0];if(!f)return;if(f.size>5*1024*1024){toast('原型本地预览限制 5MB，正式版限制另见计划。');return}state.fileName=f.name;state.importBuffer=await f.arrayBuffer();decodeNovel('UTF-8');render()}if(t.id==='encoding'&&state.importBuffer){const encoding=t.value;decodeNovel(encoding);render();$('#encoding').value=encoding}});
function decodeNovel(enc){try{state.fileText=new TextDecoder(enc).decode(state.importBuffer);const re=/^\s*(第[零一二三四五六七八九十百千万两〇\d]+[章回节][^\r\n]*)\s*$/gm;const matches=[...state.fileText.matchAll(re)];state.importChapters=matches.length?matches.map((m,i)=>({title:m[1],text:state.fileText.slice(m.index,matches[i+1]?.index)})):[{title:'正文',text:state.fileText}]}catch{toast('编码解析失败，请尝试另一种编码。')}}
document.addEventListener('input',e=>{if(e.target.id==='speed'){state.speed=e.target.value;$('#speed-val').textContent=state.speed+'×'}if(e.target.id==='voice-search')$('#voice-list').innerHTML=voiceRows(e.target.value)});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-segment]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click()}if(e.code==='Space'&&!e.target.closest('input,textarea,select,button,a,dialog,[role=button]')){e.preventDefault();playAudio()}});
const audio=$('#audio');let audioUrl;async function playAudio(){if(!audio.src){toast('请先使用右下角“载入音频”，当前没有接入语音服务。');return}try{audio.paused?await audio.play():audio.pause()}catch{toast('此音频无法播放，请尝试 MP3 或 WAV。')}}
function time(n){return Number.isFinite(n)?`${Math.floor(n/60).toString().padStart(2,'0')}:${Math.floor(n%60).toString().padStart(2,'0')}`:'00:00'}
$('#audio-file').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;audio.pause();if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=URL.createObjectURL(f);audio.src=audioUrl;$('#track-name').textContent=f.name;toast('本地音频已载入，文件不会上传。')});
audio.addEventListener('loadedmetadata',()=>$('#duration').textContent=time(audio.duration));audio.addEventListener('timeupdate',()=>{$('#clock').textContent=time(audio.currentTime);$('#seek').value=audio.duration?audio.currentTime/audio.duration*100:0});audio.addEventListener('error',()=>toast('无法解码音频，请更换 MP3 或 WAV 文件。'));for(const event of ['play','pause','ended'])audio.addEventListener(event,()=>document.querySelectorAll('.play').forEach(b=>b.textContent=audio.paused?'▶':'Ⅱ'));$('#seek').addEventListener('input',e=>{if(Number.isFinite(audio.duration))audio.currentTime=audio.duration*e.target.value/100});$('#rate').addEventListener('change',e=>audio.playbackRate=+e.target.value);window.addEventListener('hashchange',render);render();
